def transform2(g):
    from collections import Counter
    vals=Counter(x for row in g for x in row)
    bg=vals.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg:
                if c>0 and c<w-1 and g[r][c-1]!=bg and g[r][c-1]==g[r][c+1]:
                    out[r][c]=2
                elif r>0 and r<h-1 and g[r-1][c]!=bg and g[r-1][c]==g[r+1][c]:
                    out[r][c]=2
    return out

